import {useCallback, useEffect, useId, useState} from 'react';
import transform from '@diplodoc/transform';
import {
  MarkdownEditorView,
  YfmStaticView,
  useMarkdownEditor,
  type MarkupString,
  type RenderPreview,
  type RenderPreviewParams,
} from '@gravity-ui/markdown-editor';
import {Text} from '@gravity-ui/uikit';

import './MarkdownField.css';

type PreviewProps = Pick<RenderPreviewParams, 'getValue' | 'md'>;

/** Живой предпросмотр: markdown из редактора → HTML через @diplodoc/transform. */
function MarkdownPreview({getValue, md}: PreviewProps) {
  const [html, setHtml] = useState('');

  // Редактор перерисовывает предпросмотр при каждом изменении текста,
  // поэтому эффект без зависимостей: пересчёт с небольшим дебаунсом.
  useEffect(() => {
    const timer = window.setTimeout(() => {
      const {result} = transform(getValue(), {
        allowHTML: md.html,
        breaks: md.breaks,
        linkify: md.linkify,
        linkifyTlds: md.linkifyTlds,
        needToSanitizeHtml: true,
      });
      setHtml(result.html);
    }, 150);
    return () => window.clearTimeout(timer);
  });

  return (
    <YfmStaticView html={html} mods={{'no-list-reset': true}} className="markdown-field__preview" />
  );
}

export interface MarkdownFieldProps {
  label: string;
  /** Начальное значение в markdown. Поле неконтролируемое: читайте значение через onChange. */
  initialValue?: MarkupString;
  onChange?: (value: MarkupString) => void;
  placeholder?: string;
  note?: string;
  errorMessage?: string;
}

/**
 * Поле формы с markdown-разметкой и мгновенным отображением форматирования.
 * По умолчанию — режим разметки с живым предпросмотром справа (split view);
 * через меню настроек редактора можно переключиться в WYSIWYG.
 */
export function MarkdownField({
  label,
  initialValue = '',
  onChange,
  placeholder,
  note,
  errorMessage,
}: MarkdownFieldProps) {
  const labelId = useId();

  const renderPreview = useCallback<RenderPreview>(
    ({getValue, md}) => <MarkdownPreview getValue={getValue} md={md} />,
    [],
  );

  const editor = useMarkdownEditor({
    md: {html: false, linkify: true, breaks: true},
    initial: {
      markup: initialValue,
      mode: 'markup',
      toolbarVisible: true,
      splitModeEnabled: true,
    },
    markupConfig: {
      renderPreview,
      splitMode: 'horizontal',
      placeholder,
    },
  });

  useEffect(() => {
    if (!onChange) return undefined;
    const handler = () => onChange(editor.getValue());
    editor.on('change', handler);
    return () => {
      editor.off('change', handler);
    };
  }, [editor, onChange]);

  const invalid = Boolean(errorMessage);

  return (
    <div
      className={invalid ? 'markdown-field markdown-field_invalid' : 'markdown-field'}
      role="group"
      aria-labelledby={labelId}
    >
      <Text id={labelId} variant="subheader-1">
        {label}
      </Text>
      <div className="markdown-field__editor">
        <MarkdownEditorView editor={editor} stickyToolbar={false} />
      </div>
      {invalid ? (
        <Text variant="body-1" color="danger">
          {errorMessage}
        </Text>
      ) : note ? (
        <Text variant="body-1" color="secondary">
          {note}
        </Text>
      ) : null}
    </div>
  );
}
EOF

cat > src/App.tsx <<'EOF'
import {useCallback, useState, type FormEvent} from 'react';
import {Button, Flex, Text, TextInput} from '@gravity-ui/uikit';
import type {MarkupString} from '@gravity-ui/markdown-editor';

import './i18n';
import {MarkdownField} from './MarkdownField';

const INITIAL_DESCRIPTION: MarkupString = `## Описание задачи

Напишите текст с **markdown**-разметкой — форматирование видно сразу справа.

- список
- \`код\`
- [ссылка](https://gravity-ui.com)
`;

interface FormValues {
  title: string;
  description: MarkupString;
}

export function App() {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState<MarkupString>(INITIAL_DESCRIPTION);
  const [errors, setErrors] = useState<Partial<Record<keyof FormValues, string>>>({});
  const [submitted, setSubmitted] = useState<FormValues | null>(null);

  const handleDescriptionChange = useCallback((value: MarkupString) => {
    setDescription(value);
    setErrors((prev) => (prev.description ? {...prev, description: undefined} : prev));
  }, []);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const nextErrors: typeof errors = {};
    if (!title.trim()) nextErrors.title = 'Укажите заголовок';
    if (!description.trim()) nextErrors.description = 'Добавьте описание';
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length) {
      setSubmitted(null);
      return;
    }
    setSubmitted({title: title.trim(), description});
  };

  return (
    <form onSubmit={handleSubmit} noValidate style={{padding: 'var(--g-spacing-6)', maxWidth: 960}}>
      <Flex direction="column" gap={5}>
        <Text variant="header-1">Новая задача</Text>

        <TextInput
          size="l"
          label="Заголовок"
          placeholder="Коротко о задаче"
          value={title}
          onUpdate={(value) => {
            setTitle(value);
            if (errors.title) setErrors((prev) => ({...prev, title: undefined}));
          }}
          validationState={errors.title ? 'invalid' : undefined}
          errorMessage={errors.title}
          hasClear
        />

        <MarkdownField
          label="Описание"
          initialValue={INITIAL_DESCRIPTION}
          onChange={handleDescriptionChange}
          placeholder="Текст с markdown-разметкой…"
          note="Поддерживается Markdown. Режим редактора переключается в меню настроек справа на панели."
          errorMessage={errors.description}
        />

        <Flex gap={2}>
          <Button type="submit" view="action" size="l">
            Сохранить
          </Button>
        </Flex>

        {submitted ? (
          <Flex direction="column" gap={2}>
            <Text variant="subheader-2">Отправленные данные</Text>
            <Text variant="body-1">
              Заголовок: <Text variant="body-1" color="secondary">{submitted.title}</Text>
            </Text>
            <Text variant="code-1" as="pre" style={{margin: 0, whiteSpace: 'pre-wrap'}}>
              {submitted.description}
            </Text>
          </Flex>
        ) : null}
      </Flex>
    </form>
  );
}
